<?php
require_once __DIR__.'/../includes/auth.php'; require __DIR__.'/../includes/db.php';
$msg=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $user_id=(int)($_POST['user_id']??0); $date=$_POST['work_date']??date('Y-m-d'); $shift=trim($_POST['shift_name']??''); $in=$_POST['clock_in']?:null; $out=$_POST['clock_out']?:null; $notes=trim($_POST['notes']??'');
    if(!$user_id||!$date) $error='User and date are required.'; else { $stmt=$conn->prepare("INSERT INTO attendance (user_id,work_date,shift_name,clock_in,clock_out,notes) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE shift_name=VALUES(shift_name), clock_in=VALUES(clock_in), clock_out=VALUES(clock_out), notes=VALUES(notes)"); $stmt->bind_param('isssss',$user_id,$date,$shift,$in,$out,$notes); if($stmt->execute()) $msg='Attendance saved.'; else $error='Could not save attendance.'; }
}
$users=$conn->query("SELECT id,username FROM users WHERE is_active=1 ORDER BY username");
$list=$conn->query("SELECT a.*,u.username FROM attendance a JOIN users u ON a.user_id=u.id ORDER BY a.work_date DESC,a.id DESC LIMIT 200");
?>
<!DOCTYPE html><html><head><title>Attendance & Shifts</title></head><body><?php include __DIR__.'/../includes/header.php'; include __DIR__.'/../includes/leftsidebar.php';?><div class="content-page"><h2>Attendance & Shift Tracking</h2><?php if($msg):?><p class="success-msg"><?=h($msg)?></p><?php endif;?><?php if($error):?><p class="error-msg"><?=h($error)?></p><?php endif;?><div class="card-box"><form method="POST" style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;align-items:end"><div><label>User</label><select name="user_id" required><option value="">Select</option><?php while($u=$users->fetch_assoc()):?><option value="<?=h($u['id'])?>"><?=h($u['username'])?></option><?php endwhile;?></select></div><div><label>Date</label><input type="date" name="work_date" value="<?=date('Y-m-d')?>" required></div><div><label>Shift</label><input name="shift_name" placeholder="Morning / Evening"></div><div><label>Clock In</label><input type="time" name="clock_in"></div><div><label>Clock Out</label><input type="time" name="clock_out"></div><div style="grid-column:1/-1"><label>Notes</label><textarea name="notes"></textarea></div><button>Save Attendance</button></form></div><table class="table" border="1" cellpadding="10"><tr><th>Date</th><th>User</th><th>Shift</th><th>Clock In</th><th>Clock Out</th><th>Notes</th></tr><?php if($list&&$list->num_rows): while($a=$list->fetch_assoc()):?><tr><td><?=h($a['work_date'])?></td><td><?=h($a['username'])?></td><td><?=h($a['shift_name'])?></td><td><?=h($a['clock_in'])?></td><td><?=h($a['clock_out'])?></td><td><?=h($a['notes'])?></td></tr><?php endwhile;else:?><tr><td colspan="6">No attendance records.</td></tr><?php endif;?></table></div></body></html>
